def strategy(history, rng):
    n = len(history)
    if n < 5:
        return 'C'

    opp_c = 0
    my_d = 0
    for mine, opp in history:
        if opp == 'C':
            opp_c += 1
        if mine == 'D':
            my_d += 1

    opp_d = n - opp_c

    if opp_d == n:
        return 'D'

    if n == 99:
        return 'D'

    last_mine, last_opp = history[-1]
    prev_mine = history[-2][0]
    prev2_mine = history[-3][0]

    myD_C = 0
    myD_D = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                myD_C += 1
            else:
                myD_D += 1

    window = 5
    if n < window:
        window = n
    start = n - window
    rec_opp_d = 0
    rec_my_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            rec_opp_d += 1
        if history[i][0] == 'D':
            rec_my_d += 1

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    if opp_d == 0:
        if my_d == 0:
            if n >= 12:
                return 'D'
            return 'C'
        if last_mine == 'D':
            if myD_C >= 2 or my_d >= 3:
                return 'D'
            return 'C'
        return 'D'

    if opp_d > opp_c + 2 and rec_opp_d >= 2:
        if not (last_opp == 'C' and
                history[-2][1] == 'D' and
                history[-3][1] == 'D'):
            return 'D'

    if last_opp == 'C':
        if opp_c >= opp_d + 4 and rec_opp_d <= 1:
            if myD_C >= 2 and myD_C >= myD_D + 1:
                if last_mine == 'D' and myD_C < 3:
                    return 'C'
                return 'D'
            if myD_C == 1 and myD_D == 0:
                if last_mine == 'D':
                    return 'C'
                return 'D'

        if my_d == 0 and opp_c >= opp_d + 10 and rec_opp_d == 0 and n >= 40:
            return 'D'

        if (n == 98 and opp_c >= opp_d + 5 and rec_opp_d == 0 and
                myD_C >= 1 and myD_D == 0):
            return 'D'

        return 'C'

    if (last_mine == 'D' and
            my_d_streak >= 3 and
            opp_d_streak >= 3 and
            opp_c * 3 >= n * 2):
        if rng.random() < 0.3:
            return 'C'

    if last_mine == 'C' and prev_mine == 'D' and prev2_mine == 'D':
        return 'C'

    if rec_opp_d <= 1 and opp_c >= opp_d + 1:
        return 'C'

    if opp_c >= opp_d + 3 and prev_mine == 'D' and rec_my_d <= 2:
        return 'C'

    return 'D'
